from scipy import stats

def find_mode(L):
    def flatten(nested):
        result = []
        for elem in nested:
            if isinstance(elem, list):
                result.extend(flatten(elem))
            else:
                result.append(elem)
        return result

    flat_list = flatten(L)
    if not flat_list:
        raise ValueError("Input list is empty")
    mode_result = stats.mode(flat_list)
    return mode_result.mode[0]

