STEMMER = PorterStemmer()

def stem_word_freq(content):
    words = content.split()
    if not words:
        return {}
    words = words[:-1]  # Exclude the last word
    stems = []
    for word in words:
        cleaned_word = word.strip(string.punctuation)
        if cleaned_word:
            stems.append(STEMMER.stem(cleaned_word))
    return dict(Counter(stems))

