import string

def count_text_stats(text):
    word_count = len(text.split())
    filtered_chars = []
    for c in text:
        if not c.isspace() and c not in string.punctuation:
            filtered_chars.append(c)
    char_count = len(filtered_chars)
    unique_count = len(set(filtered_chars))
    return (word_count, char_count, unique_count)

