import os
import shutil

def move_files(src_dir, dest_dir, extension):
    # Normalize the extension to include a leading dot
    ext = extension.lstrip('.')
    if not ext.startswith('.'):
        ext = '.' + ext

    # Check that source and destination directories exist
    if not os.path.exists(src_dir):
        raise FileNotFoundError(f"Source directory '{src_dir}' does not exist")
    if not os.path.exists(dest_dir):
        raise FileNotFoundError(f"Destination directory '{dest_dir}' does not exist")

    files_moved = 0
    for filename in os.listdir(src_dir):
        filepath = os.path.join(src_dir, filename)
        if os.path.isfile(filepath):
            file_ext = os.path.splitext(filename)[1]
            if file_ext == ext:
                shutil.move(filepath, dest_dir)
                files_moved += 1
    return files_moved

