import base64
import hashlib
import os

def hash_password(password: str, SALT_LENGTH: int = 32) -> tuple[bytes, bytes]:
    if not password:
        raise ValueError("Password cannot be empty or None")

    salt = os.urandom(SALT_LENGTH)
    key = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, iterations=100000)
    return base64.b64encode(salt), base64.b64encode(key)

