import math

def aggregate_and_sine(nested_dict):
    aggregated = Counter()
    for inner_dict in nested_dict.values():
        for key, value in inner_dict.items():
            if key == 'ele':
                continue
            aggregated[key] += value
    return {key: math.sin(value) for key, value in aggregated.items()}

