import numpy as np
from scipy import stats

def find_mode(L):
    def flatten(nested):
        stack = list(nested)
        result = []
        while stack:
            item = stack.pop()
            if isinstance(item, list):
                stack.extend(reversed(item))
            else:
                result.append(item)
        return result

    flattened = flatten(L)
    mode_result = stats.mode(flattened)
    return int(mode_result.mode[0])

