import collections
import json
import os

def count_json_keys(directory_path):
    counts = collections.defaultdict(int)

    def traverse(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                counts[key] += 1
                traverse(value)
        elif isinstance(obj, (list, tuple)):
            for item in obj:
                traverse(item)

    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            filepath = os.path.join(directory_path, filename)
            try:
                with open(filepath, 'r') as f:
                    data = json.load(f)
                    traverse(data)
            except json.JSONDecodeError:
                continue

    return dict(counts)

import string
import random

def transform_text(text: str, seed: int = None) -> str:
    if seed is not None:
        random.seed(seed)
    transformed = []
    for char in text:
        if char.isupper():
            transformed.append(random.choice(string.ascii_uppercase))
        elif char.islower():
            transformed.append(random.choice(string.ascii_lowercase))
        else:
            transformed.append(char)
    return ''.join(transformed)

import os
import csv
from collections import Counter

def most_common_word(file_path: str) -> tuple[str, int] | None:
    if not os.path.exists(file_path) or os.path.getsize(file_path) == 0:
        return None

    words = []
    with open(file_path, 'r', encoding='utf-8') as f:
        reader = csv.reader(f)
        for row in reader:
            words.extend(word for field in row for word in field.split())

    if not words:
        return None

    counts = Counter(words)
    most_common = counts.most_common(1)[0]
    return (most_common[0], most_common[1])

