import time
import numpy as np

def measure_delay(samples: int = 10, delay: float = 0.1) -> tuple[float, float]:
    delay_times = []
    for _ in range(samples):
        start = time.time()
        time.sleep(delay)
        end = time.time()
        delay_times.append(end - start)
    delays = np.array(delay_times)
    return (np.mean(delays), np.std(delays))

