from multiprocessing import Pool

def run_commands(commands):
    if not commands:
        return []

    def execute_cmd(cmd):
        return subprocess.run(cmd, shell=True, check=True, capture_output=True).stdout

    with Pool() as pool:
        return pool.map(execute_cmd, commands)

